\title{The Fractal Dimension of Mathematical Truth: \\ Realizing the Rational Spectrum}
\author{Aristotle}
\date{2026-07-11}

\begin{document}

\begin{abstract}
We study the box-counting (fractal) dimension of \emph{theories} over a space of
statements encoded as finite binary strings. A theory assigns to each length $n$
the finite set of accepted length-$n$ strings, and its fractal dimension is the
$\limsup$ of $\log_2$ of the accepted count, normalized by length. We prove that
this dimension always lies in $[0,1]$ and is monotone under inclusion of
theories. Our main contribution is a sharp construction: for every modulus
$m \ge 1$ and every set of admissible residues $R \subseteq \{0, \dots, m-1\}$,
the \emph{periodic density theory} --- which frees coordinate $i$ exactly when
$i \bmod m \in R$ --- has fractal dimension exactly $|R|/m$, the asymptotic
density of its free coordinates. As an immediate consequence, every rational
number in $[0,1]$ is realized as the fractal dimension of some theory of truth.
This generalizes the isolated value $1/2$ found for one particular theory in
earlier work to the full rational unit interval. The engine of the proof is an
exact two-sided count of free coordinates: the counting law
$\count = 2^{\free}$, the periodicity relation $\free(n+m) = \free(n) + |R|$,
and a squeeze of the normalized logarithm to the density.
\end{abstract}

\maketitle

\section{Introduction}

The space of mathematical statements, suitably encoded, is a metric-measure
object of its own. If each statement is a finite string of bits, then the set of
statements of length $n$ is a discrete cube with $2^n$ points, and any standard
of provability or truth selects a subset of these points at each length. A
natural quantitative question follows: how densely does an accepted set sit
inside the ambient space of all strings?

The right tool is fractal (box-counting) dimension, the same notion that assigns
dimension $\log 2 / \log 3$ to the middle-thirds Cantor set. Here it measures the
exponential growth rate of the accepted count as statement length increases.
Earlier work identified a specific ``half-information'' theory with fractal
dimension exactly $1/2$, showing that truth can be sparse (dimension $< 1$) yet
non-negligible (dimension $> 0$).

This paper deepens that result. We show the value $1/2$ is not distinguished: by
tuning the density of information-bearing coordinates we realize every rational
dimension in $[0,1]$. The dimension spectrum of truth is the whole rational unit
interval. The proof rests on an exact combinatorial count and produces an
explicit witness theory for each target dimension.

\subsection*{Contributions}
\begin{enumerate}
  \item A framework in which theories over binary-string statements carry a
        well-defined box-counting dimension (Section~\ref{sec:defs}).
  \item Universal bounds: every theory has dimension in $[0,1]$
        (Theorem~\ref{thm:range}), and dimension is monotone under inclusion
        (Theorem~\ref{thm:mono}).
  \item The periodic density theorem: $\dimop(D_{m,R}) = |R|/m$
        (Theorem~\ref{thm:density}).
  \item Rational realizability: every rational in $[0,1]$ is a dimension of truth
        (Theorem~\ref{thm:rational}).
\end{enumerate}

\section{Definitions}\label{sec:defs}

Throughout, statements of length $n$ are binary strings of length $n$ (functions
from $\{0, 1, \dots, n-1\}$ to $\{\mathrm{true}, \mathrm{false}\}$); there are
$2^n$ of them.

\begin{definition}[Theory]
A \emph{theory} is a family $T$ that assigns to each length $n \in \mathbb{N}$ a
finite set $T(n)$ of accepted length-$n$ statements.
\end{definition}

\begin{definition}[Count]
The \emph{count} of a theory at length $n$ is
$\count(T, n) = |T(n)| \in \mathbb{N}$.
\end{definition}

\begin{definition}[Finite-scale dimension estimate]
For $n \ge 1$,
\[
  \dimEst(T, n) = \frac{\log_2 \count(T, n)}{n},
\]
with the convention $\log_2 0 = 0$, so the estimate is defined even when the
theory accepts nothing at length $n$.
\end{definition}

\begin{definition}[Box-counting / fractal dimension]
\[
  \dimop(T) = \limsup_{n \to \infty} \dimEst(T, n)
            = \limsup_{n \to \infty} \frac{\log_2 \count(T, n)}{n}.
\]
\end{definition}

The $\limsup$ (rather than a plain limit) is essential: for irregular theories
the estimate can oscillate indefinitely, and the $\limsup$ records the coarsest
scale at which the accepted set is thick. For the regular theories of
Section~\ref{sec:density} the estimate converges, so $\limsup$ and $\lim$
coincide.

\section{Universal bounds and monotonicity}

\begin{lemma}[Trivial count bound]\label{lem:countbound}
For every theory $T$ and every $n$, $\count(T,n) \le 2^n$.
\end{lemma}
\begin{proof}
$T(n)$ is a subset of the set of all $2^n$ length-$n$ strings, and the
cardinality of a subset is at most that of the whole.
\end{proof}

Taking $\log_2$ of the bound (monotonicity of $\log_2$ on the positive reals,
with the $\log_2 0 = 0$ convention handling the empty case) gives
$\log_2 \count(T, n) \le n$, hence the following.

\begin{lemma}[Estimate range]\label{lem:estrange}
For $n \ge 1$, $0 \le \dimEst(T, n) \le 1$.
\end{lemma}
\begin{proof}
Nonnegativity: $\count(T,n) \ge 0$ and, when positive, $\count(T,n) \ge 1$, so
$\log_2 \count(T,n) \ge 0$; dividing by $n > 0$ preserves the sign. Upper bound:
$\log_2 \count(T,n) \le n$ divided by $n$ gives $\le 1$.
\end{proof}

\begin{theorem}[Dimension lies in the unit interval]\label{thm:range}
For every theory $T$, $0 \le \dimop(T) \le 1$.
\end{theorem}
\begin{proof}
The sequence $\dimEst(T, \cdot)$ is eventually bounded below by $0$ and above by
$1$ (Lemma~\ref{lem:estrange}). The $\limsup$ of a sequence eventually contained
in $[0,1]$ lies in $[0,1]$; since the estimate is bounded and co-bounded under
the eventual filter, its $\limsup$ is a genuine real number in the stated range.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:mono}
If $T(n) \subseteq T'(n)$ for all $n$, then $\dimop(T) \le \dimop(T')$.
\end{theorem}
\begin{proof}
Inclusion of finite sets gives $\count(T,n) \le \count(T',n)$ for all $n$. Since
$\log_2$ is monotone on positive reals (and the $\log_2 0 = 0$ convention keeps
the inequality valid at the empty count, where the left side is $0$), dividing by
$n \ge 0$ yields $\dimEst(T,n) \le \dimEst(T',n)$ for all $n$. The $\limsup$ is
monotone with respect to eventual pointwise domination, so
$\dimop(T) \le \dimop(T')$.
\end{proof}

\section{Periodic density theories and the rational spectrum}\label{sec:density}

\begin{definition}[Periodic density theory]
Fix a modulus $m \ge 1$ and a set of admissible residues
$R \subseteq \{0, 1, \dots, m-1\}$. The \emph{periodic density theory} $D_{m,R}$
accepts at length $n$ exactly those strings for which every non-admissible
coordinate is false; that is, coordinate $i$ is \emph{free} (may be true or
false) when $i \bmod m \in R$ and is \emph{forced} to false otherwise:
\[
  D_{m,R}(n) = \prod_{i < n}
  \begin{cases}
    \{\mathrm{true}, \mathrm{false}\}, & i \bmod m \in R,\\
    \{\mathrm{false}\}, & i \bmod m \notin R.
  \end{cases}
\]
\end{definition}

\begin{definition}[Free count]
The number of free (admissible) coordinates below $n$ is
\[
  \free(m, R, n) = \big|\{\, i < n : i \bmod m \in R \,\}\big|.
\]
\end{definition}

\begin{lemma}[Exact counting law]\label{lem:count}
For all $m, R, n$, $\count(D_{m,R}, n) = 2^{\,\free(m,R,n)}$.
\end{lemma}
\begin{proof}
The accepted set is a product over coordinates: each free coordinate
independently takes $2$ values and each forced coordinate takes exactly $1$. The
cardinality of a product of finite sets is the product of the cardinalities, so
\[
  \count(D_{m,R}, n)
  = \prod_{i<n} \big(\text{$2$ if $i \bmod m \in R$ else $1$}\big)
  = 2^{\,|\{i<n:\, i \bmod m \in R\}|}
  = 2^{\free(m,R,n)}. \qedhere
\]
\end{proof}

Over any block of $m$ consecutive indices, $\{0,1,\dots,m-1\}$ cycles through a
complete residue system, so exactly $|R|$ of them are admissible. Hence
$\free(m,R,n+m) = \free(m,R,n) + |R|$, and by induction on the number of complete
blocks,
\begin{equation}\label{eq:sandwich}
  |R|\cdot\Big\lfloor \tfrac{n}{m} \Big\rfloor
  \;\le\; \free(m,R,n)
  \;\le\; |R|\cdot\Big\lfloor \tfrac{n}{m} \Big\rfloor + |R|.
\end{equation}
The lower bound counts only coordinates in the $\lfloor n/m\rfloor$ complete
blocks below $n$; the upper bound adds the at most $|R|$ admissible coordinates
in the final incomplete block.

\begin{theorem}[Dimension of a periodic density theory]\label{thm:density}
For every $m \ge 1$ and $R \subseteq \{0,\dots,m-1\}$,
$\dimop(D_{m,R}) = |R|/m$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:count}, $\log_2 \count(D_{m,R}, n) = \free(m,R,n)$, so
$\dimEst(D_{m,R}, n) = \free(m,R,n)/n$. Divide the sandwich~\eqref{eq:sandwich}
by $n$. Using $\lfloor n/m \rfloor = n/m - \{n/m\}$ with fractional part in
$[0,1)$, both the lower bound $\frac{|R|}{m}\cdot\frac{m\lfloor n/m\rfloor}{n}$
and the upper bound
$\frac{|R|}{m}\cdot\frac{m\lfloor n/m\rfloor}{n} + \frac{|R|}{n}$ converge to
$|R|/m$: the first because $m\lfloor n/m\rfloor / n \to 1$, the second because
additionally $|R|/n \to 0$. By the squeeze theorem
$\dimEst(D_{m,R},n) \to |R|/m$, and a convergent sequence has $\limsup$ equal to
its limit, so $\dimop(D_{m,R}) = |R|/m$.
\end{proof}

The proof depends only on $|R|$, never on which residues are admissible. This
robustness is exactly what makes the full rational interval attainable.

\begin{theorem}[Rational realizability]\label{thm:rational}
For every rational $q \in [0,1]$ there is a theory $T$ with $\dimop(T) = q$.
\end{theorem}
\begin{proof}
Write $q = p/m$ with $0 \le p \le m$ and $m \ge 1$. Choose any
$R \subseteq \{0, \dots, m-1\}$ with $|R| = p$, for instance
$R = \{0, 1, \dots, p-1\}$. By Theorem~\ref{thm:density},
$\dimop(D_{m,R}) = |R|/m = p/m = q$.
\end{proof}

\begin{corollary}
The set $\{\dimop(T) : T \text{ a theory}\}$ contains every rational in $[0,1]$
and is therefore dense in $[0,1]$. The value $1/2$ of the base development is one
point of this spectrum, realized by $m = 2$, $R = \{0\}$.
\end{corollary}

\section{Discussion}

The heart of the argument is that the box dimension of a periodic density theory
equals the asymptotic density of its free coordinates, established through the
exact count $\count = 2^{\free}$ and an elementary squeeze. Two features deserve
emphasis. First, the count is exact, so nothing is lost to estimation before the
limiting step; the only inequalities are the clean block-counting
bounds~\eqref{eq:sandwich}. Second, the dimension is density-driven: it ignores
the arithmetic identity of the admissible residues, which is precisely why the
whole rational interval --- not a sparse subset --- is realized.

The use of $\limsup$ rather than $\lim$ is not idle generality. For irregular
theories the finite estimate genuinely oscillates, and the $\limsup$ is the
correct dimension. The periodic theories are asymptotically regular, which
collapses the $\limsup$ to a limit.

\section{Future work}

\begin{conjecture}[Full real spectrum]
For every real $d \in [0,1]$ there is a theory of dimension $d$; the squeeze
argument used only that the free-coordinate count grows like $d\cdot n + o(n)$,
so any coordinate set of density $d$ should yield dimension exactly $d$.
\end{conjecture}

\begin{conjecture}[Dimension calculus]
The dimension of a pointwise union of theories equals the maximum of the two
dimensions, and the dimension of an independent product adds, capped at $1$.
\end{conjecture}

\begin{conjecture}[Measure-zero fractal truth]
Extended to infinite strings, the periodic construction yields a self-similar
Cantor-like set whose Hausdorff dimension equals the coordinate density $d$ while
its Lebesgue measure is zero.
\end{conjecture}

\section{Conclusion}

The fractal dimension of a theory of truth is exactly the asymptotic density of
its information-bearing coordinates, and consequently every rational number in
$[0,1]$ arises as such a dimension, each realized by a concrete periodic theory.
The dimension spectrum of truth is the entire rational unit interval; the
isolated value $1/2$ is revealed as a single point in a continuum-in-waiting.

\end{document}

