function DimEstimate(m, R, n):
    free      <- FreeCount(m, R, n)         # closed form
    estimate  <- free / n
    exact_dim <- |R| / m
    error_bd  <- |R| / n                    # certified bound
    return (estimate, exact_dim, error_bd)

