from fractions import Fraction
from typing import FrozenSet, Tuple

def free_count(m: int, R: FrozenSet[int], n: int) -> int:
    return len(R) * (n // m) + sum(1 for r in R if r < n % m)

def dim_estimate_with_bound(
    m: int, R: FrozenSet[int], n: int
) -> Tuple[float, Fraction, float]:
    """Return (estimate, exact |R|/m, certified error bound |R|/n)."""
    free: int = free_count(m, R, n)
    estimate: float = free / n
    exact_dim: Fraction = Fraction(len(R), m)
    error_bound: float = len(R) / n
    return estimate, exact_dim, error_bound
